#include <bits/stdc++.h>

using namespace std;

const int MOD = 1000000007;
const int MAX_SIZE = 1 << 20;

int mod_pow(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (1LL * res * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

const int M = 21;

int n;
int array_f[MAX_SIZE], array_g[MAX_SIZE];
int probability[M][M];

int index_map[2][MAX_SIZE];
int rev_mask[MAX_SIZE];
int match[M];
int adj[M][M];

void compute(int *f, vector<int> left, vector<int> right, vector<int> subgraph, int *idx) {
    vector<pair<int, int>> edges;
    for (auto x : left) {
        for (auto y : right) {
            edges.emplace_back(x, y);
        }
    }

    for (int mask = 0; mask < (1 << (int)edges.size()); ++mask) {
        int prob = 1;
        for (int i = 0; i < (int)edges.size(); ++i) {
            if (mask & (1 << i)) {
                prob = (1LL * prob * probability[edges[i].first][edges[i].second]) % MOD;
                adj[edges[i].first][edges[i].second] = 1;
            } else {
                prob = (1LL * prob * (MOD + 1 - probability[edges[i].first][edges[i].second])) % MOD;
                adj[edges[i].first][edges[i].second] = 0;
            }
        }
        for (auto g : subgraph) {
            vector<int> perm, indices;
            for (auto x : left) perm.push_back(x);
            for (int i = 0; i < n; ++i) if (g & (1 << i)) indices.push_back(i + n);
            bool found = false;
            do {
                bool valid = true;
                for (int i = 0; i < (int)perm.size(); ++i) {
                    if (!adj[perm[i]][indices[i]]) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    found = true;
                    break;
                }
            } while (next_permutation(indices.begin(), indices.end()));
            if (found) {
                int mask_idx = idx[g];
                rev_mask[mask] |= (1 << mask_idx);
            }
        }
        f[0] = (f[0] + prob) % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> probability[i][j + n];
            probability[i][j + n] = (1LL * probability[i][j + n] * mod_pow(100, MOD - 2)) % MOD;
        }
    }

    if (n == 1) {
        cout << probability[0][1] << "\n";
        return 0;
    }

    int size1 = n / 2;
    int size2 = n - size1;

    int count1 = 0, count2 = 0;
    vector<int> subset1, subset2;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (__builtin_popcount(mask) == size1) {
            index_map[0][mask] = count1++;
            subset1.push_back(mask);
        }
        if (__builtin_popcount(mask) == size2) {
            index_map[1][mask] = count2++;
            subset2.push_back(mask);
        }
    }

    for (int i = 0; i < (int)subset2.size(); ++i) {
        int mask = subset2[i];
        for (int big_mask = 0; big_mask < (1 << count2); ++big_mask) {
            if (big_mask & (1 << i))
                rev_mask[big_mask] |= (1 << index_map[0][(1 << n) - 1 - mask]);
        }
    }

    vector<int> left_part1, left_part2, right_part;
    for (int i = n; i < 2 * n; ++i) {
        right_part.push_back(i);
    }
    for (int i = 0; i < size1; ++i) left_part1.push_back(i);
    for (int i = size1; i < n; ++i) left_part2.push_back(i);

    compute(array_f, left_part1, right_part, subset1, index_map[0]);
    compute(array_g, left_part2, right_part, subset2, index_map[1]);

    for (int i = 0; i < count1; ++i) {
        for (int mask = 0; mask < (1 << count1); ++mask) {
            if (mask & (1 << i))
                array_f[mask] = (array_f[mask] + array_f[mask ^ (1 << i)]) % MOD;
        }
    }

    long long total = 0;
    for (int mask = 1; mask < (1 << count2); ++mask) {
        int w = (1 - array_f[(1 << count1) - 1 - rev_mask[mask]] + MOD) % MOD;
        total = (total + 1LL * w * array_g[mask]) % MOD;
    }

    cout << total << "\n";

    return 0;
}
